function bestCashIn(nums: number[]): number {
  const max = Math.max(...nums);
  const gain = new Array(max + 1).fill(0);
  for (const x of nums) gain[x] += x;
  let prev2 = 0, prev1 = 0;
  for (let v = 0; v <= max; v++) {
    const cur = Math.max(prev1, prev2 + gain[v]);
    prev2 = prev1;
    prev1 = cur;
  }
  return prev1;
}

