function bestCashIn(nums: number[]): number {
  const total = new Map<number, number>();
  for (const x of nums) total.set(x, (total.get(x) ?? 0) + x);
  const values = [...total.keys()].sort((a, b) => a - b);
  let take = 0, skip = 0, last = -2;
  for (const v of values) {
    const best = Math.max(take, skip);
    // taking v is only blocked if the previous value was v - 1
    take = (v === last + 1 ? skip : best) + total.get(v)!;
    skip = best;
    last = v;
  }
  return Math.max(take, skip);
}

