        total = Counter()
        for x in nums:
            total[x] += x
        take = skip = 0
        last = -2
        for v in sorted(total):
            best = max(take, skip)
            # taking v is only blocked if the previous value was v - 1
            take = (skip if v == last + 1 else best) + total[v]
            skip = best
            last = v
        return max(take, skip)

